using System.IO;
using Microsoft.Data.Sqlite;
using DirectorFamilyTravelDesk.Models;
using System.Globalization;
using System.Text;

namespace DirectorFamilyTravelDesk.Data;

public sealed class TravelRepository
{
    private readonly string _dbPath;
    private readonly string _cs;
    public string DatabasePath => _dbPath;
    public TravelRepository(string dbPath) { _dbPath=dbPath; _cs=$"Data Source={dbPath};Cache=Shared;Mode=ReadWriteCreate"; }
    private SqliteConnection Open() { var c=new SqliteConnection(_cs); c.Open(); using var cmd=c.CreateCommand(); cmd.CommandText="PRAGMA foreign_keys=ON; PRAGMA busy_timeout=3000;"; cmd.ExecuteNonQuery(); return c; }
    public void Initialize(){ using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText="PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL;"; cmd.ExecuteNonQuery(); }
    private static DateTime ParseDate(string s)=>DateTime.ParseExact(s,"yyyy-MM-dd",CultureInfo.InvariantCulture);
    private static DateTime? ParseNullableDate(object v)=>v is DBNull?null:ParseDate((string)v);

    public List<CityItem> GetCities(bool activeOnly=true)
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText="SELECT id,name,iata,is_active FROM cities"+(activeOnly?" WHERE is_active=1":"")+" ORDER BY name"; using var r=cmd.ExecuteReader(); var a=new List<CityItem>(); while(r.Read())a.Add(new(){Id=r.GetInt64(0),Name=r.GetString(1),Iata=r.GetString(2),IsActive=r.GetInt64(3)==1}); return a; }
    public List<TravellerItem> GetTravellers(bool activeOnly=true)
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText="SELECT id,short_code,full_name,relation_group,is_active FROM travellers"+(activeOnly?" WHERE is_active=1":"")+" ORDER BY short_code"; using var r=cmd.ExecuteReader(); var a=new List<TravellerItem>(); while(r.Read())a.Add(new(){Id=r.GetInt64(0),ShortCode=r.GetString(1),FullName=r.IsDBNull(2)?null:r.GetString(2),RelationGroup=r.IsDBNull(3)?null:r.GetString(3),IsActive=r.GetInt64(4)==1}); return a; }
    public List<RouteItem> GetRoutes(bool activeOnly=true)
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText=@"SELECT r.id,r.from_city_id,r.to_city_id,r.route_code,r.route_label,cf.name,ct.name,r.is_active FROM routes r JOIN cities cf ON cf.id=r.from_city_id JOIN cities ct ON ct.id=r.to_city_id"+(activeOnly?" WHERE r.is_active=1":"")+" ORDER BY cf.name,ct.name"; using var r=cmd.ExecuteReader(); var a=new List<RouteItem>(); while(r.Read())a.Add(new(){Id=r.GetInt64(0),FromCityId=r.GetInt64(1),ToCityId=r.GetInt64(2),RouteCode=r.GetString(3),RouteLabel=r.GetString(4),FromCity=r.GetString(5),ToCity=r.GetString(6),IsActive=r.GetInt64(7)==1}); return a; }
    public RouteItem? GetReverseRoute(long routeId)
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText=@"SELECT rr.id,rr.from_city_id,rr.to_city_id,rr.route_code,rr.route_label,cf.name,ct.name,rr.is_active FROM routes r JOIN routes rr ON rr.from_city_id=r.to_city_id AND rr.to_city_id=r.from_city_id JOIN cities cf ON cf.id=rr.from_city_id JOIN cities ct ON ct.id=rr.to_city_id WHERE r.id=$id LIMIT 1"; cmd.Parameters.AddWithValue("$id",routeId); using var r=cmd.ExecuteReader(); if(!r.Read())return null; return new(){Id=r.GetInt64(0),FromCityId=r.GetInt64(1),ToCityId=r.GetInt64(2),RouteCode=r.GetString(3),RouteLabel=r.GetString(4),FromCity=r.GetString(5),ToCity=r.GetString(6),IsActive=r.GetInt64(7)==1}; }
    public List<FlightItem> GetFlights(long routeId, bool activeOnly=true)
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText=@"SELECT f.id,f.airline,f.flight_no,f.route_id,r.route_code,f.departure_time,f.arrival_time,f.stops,f.via_iata,f.display_value,f.is_active FROM flights f JOIN routes r ON r.id=f.route_id WHERE f.route_id=$rid"+(activeOnly?" AND f.is_active=1":"")+" ORDER BY f.departure_time,f.airline,f.flight_no"; cmd.Parameters.AddWithValue("$rid",routeId); using var r=cmd.ExecuteReader(); var a=new List<FlightItem>(); while(r.Read())a.Add(new(){Id=r.GetInt64(0),Airline=r.GetString(1),FlightNo=r.GetString(2),RouteId=r.GetInt64(3),RouteCode=r.GetString(4),DepartureTime=r.GetString(5),ArrivalTime=r.GetString(6),Stops=r.GetInt32(7),ViaIata=r.IsDBNull(8)?null:r.GetString(8),DisplayValue=r.GetString(9),IsActive=r.GetInt64(10)==1}); return a; }
    public List<FlightItem> GetAllFlights()
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText=@"SELECT f.id,f.airline,f.flight_no,f.route_id,r.route_code,f.departure_time,f.arrival_time,f.stops,f.via_iata,f.display_value,f.is_active FROM flights f JOIN routes r ON r.id=f.route_id ORDER BY r.route_code,f.departure_time"; using var r=cmd.ExecuteReader(); var a=new List<FlightItem>(); while(r.Read())a.Add(new(){Id=r.GetInt64(0),Airline=r.GetString(1),FlightNo=r.GetString(2),RouteId=r.GetInt64(3),RouteCode=r.GetString(4),DepartureTime=r.GetString(5),ArrivalTime=r.GetString(6),Stops=r.GetInt32(7),ViaIata=r.IsDBNull(8)?null:r.GetString(8),DisplayValue=r.GetString(9),IsActive=r.GetInt64(10)==1}); return a; }
    public List<LookupItem> GetLookup(string table)
    { var allowed=new HashSet<string>{"transport_options","status_options","hotel_options","trip_types"}; if(!allowed.Contains(table))throw new ArgumentException("Invalid lookup table"); using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText=$"SELECT id,name FROM {table} WHERE is_active=1 ORDER BY "+(table=="status_options"?"sort_order":"name"); using var r=cmd.ExecuteReader(); var a=new List<LookupItem>(); while(r.Read())a.Add(new(){Id=r.GetInt64(0),Name=r.GetString(1)}); return a; }
    public List<TripListItem> GetTrips()
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText=@"
SELECT t.id,t.trip_code,t.departure_date,t.return_date,t.route_id,r.route_label,
 COALESCE((SELECT group_concat(tv2.short_code, ', ') FROM trip_travellers tt2 JOIN travellers tv2 ON tv2.id=tt2.traveller_id WHERE tt2.trip_id=t.id),'') travellers,
 (SELECT count(*) FROM trip_travellers tt3 WHERE tt3.trip_id=t.id) pax,
 ofl.display_value,t.onward_pnr,t.onward_seats,rfl.display_value,t.return_pnr,t.return_seats,h.name,tr.name,t.transport_details,t.total_cost,s.name,s.next_action,t.remarks
FROM trips t JOIN routes r ON r.id=t.route_id
LEFT JOIN flights ofl ON ofl.id=t.onward_flight_id LEFT JOIN flights rfl ON rfl.id=t.return_flight_id
LEFT JOIN hotel_options h ON h.id=t.hotel_option_id LEFT JOIN transport_options tr ON tr.id=t.transport_option_id
LEFT JOIN status_options s ON s.id=t.status_option_id ORDER BY t.departure_date,t.trip_code"; using var r=cmd.ExecuteReader(); var a=new List<TripListItem>(); while(r.Read())a.Add(new(){Id=r.GetInt64(0),TripCode=r.GetString(1),DepartureDate=ParseDate(r.GetString(2)),ReturnDate=ParseNullableDate(r.GetValue(3)),RouteId=r.GetInt64(4),RouteLabel=r.GetString(5),Travellers=r.GetString(6),Pax=r.GetInt32(7),OnwardFlight=r.IsDBNull(8)?null:r.GetString(8),OnwardPnr=r.IsDBNull(9)?null:r.GetString(9),OnwardSeats=r.IsDBNull(10)?null:r.GetString(10),ReturnFlight=r.IsDBNull(11)?null:r.GetString(11),ReturnPnr=r.IsDBNull(12)?null:r.GetString(12),ReturnSeats=r.IsDBNull(13)?null:r.GetString(13),Hotel=r.IsDBNull(14)?null:r.GetString(14),Transport=r.IsDBNull(15)?null:r.GetString(15),TransportDetails=r.IsDBNull(16)?null:r.GetString(16),TotalCost=r.IsDBNull(17)?null:Convert.ToDecimal(r.GetValue(17),CultureInfo.InvariantCulture),Status=r.IsDBNull(18)?null:r.GetString(18),NextAction=r.IsDBNull(19)?null:r.GetString(19),Remarks=r.IsDBNull(20)?null:r.GetString(20)}); return a; }
    public TripEditModel? GetTrip(long id)
    { using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText=@"SELECT id,trip_code,departure_date,return_date,trip_type_id,route_id,onward_flight_id,return_flight_id,onward_pnr,onward_seats,return_pnr,return_seats,hotel_option_id,transport_option_id,transport_details,total_cost,status_option_id,remarks FROM trips WHERE id=$id"; cmd.Parameters.AddWithValue("$id",id); using var r=cmd.ExecuteReader(); if(!r.Read())return null; var m=new TripEditModel{Id=r.GetInt64(0),TripCode=r.GetString(1),DepartureDate=ParseDate(r.GetString(2)),ReturnDate=ParseNullableDate(r.GetValue(3)),TripTypeId=r.IsDBNull(4)?0:r.GetInt64(4),RouteId=r.GetInt64(5),OnwardFlightId=r.IsDBNull(6)?null:r.GetInt64(6),ReturnFlightId=r.IsDBNull(7)?null:r.GetInt64(7),OnwardPnr=r.IsDBNull(8)?null:r.GetString(8),OnwardSeats=r.IsDBNull(9)?null:r.GetString(9),ReturnPnr=r.IsDBNull(10)?null:r.GetString(10),ReturnSeats=r.IsDBNull(11)?null:r.GetString(11),HotelOptionId=r.IsDBNull(12)?null:r.GetInt64(12),TransportOptionId=r.IsDBNull(13)?null:r.GetInt64(13),TransportDetails=r.IsDBNull(14)?null:r.GetString(14),TotalCost=r.IsDBNull(15)?null:r.GetDecimal(15),StatusOptionId=r.IsDBNull(16)?null:r.GetInt64(16),Remarks=r.IsDBNull(17)?null:r.GetString(17)}; r.Close(); using var tc=c.CreateCommand(); tc.CommandText="SELECT traveller_id FROM trip_travellers WHERE trip_id=$id"; tc.Parameters.AddWithValue("$id",id); using var tr=tc.ExecuteReader(); while(tr.Read())m.TravellerIds.Add(tr.GetInt64(0)); return m; }
    public string NextTripCode()
    { var year=DateTime.Today.Year; using var c=Open(); using var cmd=c.CreateCommand(); cmd.CommandText="SELECT trip_code FROM trips WHERE trip_code LIKE $p ORDER BY trip_code DESC LIMIT 1"; cmd.Parameters.AddWithValue("$p",$"TR-{year}-%"); var v=cmd.ExecuteScalar()?.ToString(); var n=1; if(v!=null && int.TryParse(v.Split('-').Last(),out var x))n=x+1; return $"TR-{year}-{n:000}"; }
    public void SaveTrip(TripEditModel m)
    { using var c=Open(); using var tx=c.BeginTransaction(); long id=m.Id; using(var cmd=c.CreateCommand()){cmd.Transaction=tx; if(id==0){cmd.CommandText=@"INSERT INTO trips(trip_code,departure_date,return_date,trip_type_id,route_id,onward_flight_id,return_flight_id,onward_pnr,onward_seats,return_pnr,return_seats,hotel_option_id,transport_option_id,transport_details,total_cost,status_option_id,remarks) VALUES($code,$dep,$ret,$type,$route,$of,$rf,$opnr,$oseat,$rpnr,$rseat,$hotel,$transport,$td,$cost,$status,$remarks); SELECT last_insert_rowid();";}else{cmd.CommandText=@"UPDATE trips SET trip_code=$code,departure_date=$dep,return_date=$ret,trip_type_id=$type,route_id=$route,onward_flight_id=$of,return_flight_id=$rf,onward_pnr=$opnr,onward_seats=$oseat,return_pnr=$rpnr,return_seats=$rseat,hotel_option_id=$hotel,transport_option_id=$transport,transport_details=$td,total_cost=$cost,status_option_id=$status,remarks=$remarks,updated_at=CURRENT_TIMESTAMP WHERE id=$id"; cmd.Parameters.AddWithValue("$id",id);} cmd.Parameters.AddWithValue("$code",m.TripCode); cmd.Parameters.AddWithValue("$dep",m.DepartureDate.ToString("yyyy-MM-dd")); cmd.Parameters.AddWithValue("$ret",(object?)m.ReturnDate?.ToString("yyyy-MM-dd")??DBNull.Value); cmd.Parameters.AddWithValue("$type",m.TripTypeId==0?DBNull.Value:m.TripTypeId); cmd.Parameters.AddWithValue("$route",m.RouteId); cmd.Parameters.AddWithValue("$of",(object?)m.OnwardFlightId??DBNull.Value); cmd.Parameters.AddWithValue("$rf",(object?)m.ReturnFlightId??DBNull.Value); cmd.Parameters.AddWithValue("$opnr",(object?)m.OnwardPnr??DBNull.Value); cmd.Parameters.AddWithValue("$oseat",(object?)m.OnwardSeats??DBNull.Value); cmd.Parameters.AddWithValue("$rpnr",(object?)m.ReturnPnr??DBNull.Value); cmd.Parameters.AddWithValue("$rseat",(object?)m.ReturnSeats??DBNull.Value); cmd.Parameters.AddWithValue("$hotel",(object?)m.HotelOptionId??DBNull.Value); cmd.Parameters.AddWithValue("$transport",(object?)m.TransportOptionId??DBNull.Value); cmd.Parameters.AddWithValue("$td",(object?)m.TransportDetails??DBNull.Value); cmd.Parameters.AddWithValue("$cost",(object?)m.TotalCost??DBNull.Value); cmd.Parameters.AddWithValue("$status",(object?)m.StatusOptionId??DBNull.Value); cmd.Parameters.AddWithValue("$remarks",(object?)m.Remarks??DBNull.Value); var result=cmd.ExecuteScalar(); if(m.Id==0)id=(long)(result??0L);}
      using(var d=c.CreateCommand()){d.Transaction=tx;d.CommandText="DELETE FROM trip_travellers WHERE trip_id=$id";d.Parameters.AddWithValue("$id",id);d.ExecuteNonQuery();}
      foreach(var travellerId in m.TravellerIds){using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT OR IGNORE INTO trip_travellers(trip_id,traveller_id) VALUES($t,$v)";q.Parameters.AddWithValue("$t",id);q.Parameters.AddWithValue("$v",travellerId);q.ExecuteNonQuery();}
      tx.Commit(); }
    public void DeleteTrip(long id){using var c=Open();using var cmd=c.CreateCommand();cmd.CommandText="DELETE FROM trips WHERE id=$id";cmd.Parameters.AddWithValue("$id",id);cmd.ExecuteNonQuery();}

    public long SaveCity(CityItem x){using var c=Open();using var cmd=c.CreateCommand(); if(x.Id==0)cmd.CommandText="INSERT INTO cities(name,iata,is_active) VALUES($n,$i,$a); SELECT last_insert_rowid();";else{cmd.CommandText="UPDATE cities SET name=$n,iata=$i,is_active=$a WHERE id=$id; SELECT $id";cmd.Parameters.AddWithValue("$id",x.Id);}cmd.Parameters.AddWithValue("$n",x.Name.Trim());cmd.Parameters.AddWithValue("$i",x.Iata.Trim().ToUpperInvariant());cmd.Parameters.AddWithValue("$a",x.IsActive?1:0);return (long)(cmd.ExecuteScalar()??0L);}
    public long SaveTraveller(TravellerItem x){using var c=Open();using var cmd=c.CreateCommand(); if(x.Id==0)cmd.CommandText="INSERT INTO travellers(short_code,full_name,relation_group,is_active) VALUES($s,$f,$g,$a); SELECT last_insert_rowid();";else{cmd.CommandText="UPDATE travellers SET short_code=$s,full_name=$f,relation_group=$g,is_active=$a WHERE id=$id; SELECT $id";cmd.Parameters.AddWithValue("$id",x.Id);}cmd.Parameters.AddWithValue("$s",x.ShortCode.Trim().ToUpperInvariant());cmd.Parameters.AddWithValue("$f",(object?)x.FullName??DBNull.Value);cmd.Parameters.AddWithValue("$g",(object?)x.RelationGroup??DBNull.Value);cmd.Parameters.AddWithValue("$a",x.IsActive?1:0);return (long)(cmd.ExecuteScalar()??0L);}
    public long SaveRoute(RouteItem x){using var c=Open();var from=GetCities(false).First(z=>z.Id==x.FromCityId);var to=GetCities(false).First(z=>z.Id==x.ToCityId);var code=$"{from.Iata}-{to.Iata}";var label=$"{from.Iata} → {to.Iata}";using var cmd=c.CreateCommand();if(x.Id==0)cmd.CommandText="INSERT INTO routes(from_city_id,to_city_id,route_code,route_label,is_active) VALUES($f,$t,$c,$l,$a); SELECT last_insert_rowid();";else{cmd.CommandText="UPDATE routes SET from_city_id=$f,to_city_id=$t,route_code=$c,route_label=$l,is_active=$a WHERE id=$id; SELECT $id";cmd.Parameters.AddWithValue("$id",x.Id);}cmd.Parameters.AddWithValue("$f",x.FromCityId);cmd.Parameters.AddWithValue("$t",x.ToCityId);cmd.Parameters.AddWithValue("$c",code);cmd.Parameters.AddWithValue("$l",label);cmd.Parameters.AddWithValue("$a",x.IsActive?1:0);return (long)(cmd.ExecuteScalar()??0L);}
    public long SaveFlight(FlightItem x){using var c=Open();var route=GetRoutes(false).First(z=>z.Id==x.RouteId);var display=$"{x.FlightNo.Trim()} | {route.RouteCode} | {x.DepartureTime}-{x.ArrivalTime}";using var cmd=c.CreateCommand();if(x.Id==0)cmd.CommandText="INSERT INTO flights(airline,flight_no,route_id,departure_time,arrival_time,stops,via_iata,display_value,is_active) VALUES($a,$f,$r,$d,$ar,$s,$v,$dv,$act); SELECT last_insert_rowid();";else{cmd.CommandText="UPDATE flights SET airline=$a,flight_no=$f,route_id=$r,departure_time=$d,arrival_time=$ar,stops=$s,via_iata=$v,display_value=$dv,is_active=$act WHERE id=$id; SELECT $id";cmd.Parameters.AddWithValue("$id",x.Id);}cmd.Parameters.AddWithValue("$a",x.Airline.Trim());cmd.Parameters.AddWithValue("$f",x.FlightNo.Trim());cmd.Parameters.AddWithValue("$r",x.RouteId);cmd.Parameters.AddWithValue("$d",x.DepartureTime);cmd.Parameters.AddWithValue("$ar",x.ArrivalTime);cmd.Parameters.AddWithValue("$s",x.Stops);cmd.Parameters.AddWithValue("$v",(object?)x.ViaIata??DBNull.Value);cmd.Parameters.AddWithValue("$dv",display);cmd.Parameters.AddWithValue("$act",x.IsActive?1:0);return (long)(cmd.ExecuteScalar()??0L);}

    public void Backup(string destination){File.Copy(_dbPath,destination,true);}
    public void ExportTripsCsv(string path)
    { var rows=GetTrips(); var sb=new StringBuilder(); sb.AppendLine("Trip ID,Departure,Return,Route,Travellers,Pax,Onward,Onward PNR,Seats,Return Flight,Return PNR,Seats,Hotel,Transport,Transport Details,Total Cost,Status,Next Action,Remarks"); static string E(string? s)=>"\""+(s??"").Replace("\"","\"\"")+"\""; foreach(var x in rows)sb.AppendLine(string.Join(',',E(x.TripCode),E(x.DepartureDate.ToString("dd-MMM-yyyy")),E(x.ReturnDate?.ToString("dd-MMM-yyyy")),E(x.RouteLabel),E(x.Travellers),x.Pax,E(x.OnwardFlight),E(x.OnwardPnr),E(x.OnwardSeats),E(x.ReturnFlight),E(x.ReturnPnr),E(x.ReturnSeats),E(x.Hotel),E(x.Transport),E(x.TransportDetails),x.TotalCost?.ToString("0.00",CultureInfo.InvariantCulture)??"",E(x.Status),E(x.NextAction),E(x.Remarks))); File.WriteAllText(path,sb.ToString(),Encoding.UTF8); }
}